class Solution {
public:
    int minSteps(int n) {
        int ans = 0;
        int d = 2;
        while (n > 1) {
            while (n % d == 0) {
                ans += d;
                n /= d;
            }
            ++d;
        }
        return ans;
    }
};

class Solution {
    public int minSteps(int n) {
        int ans = 0;
        int d = 2;
        while (n > 1) {
            while (n % d == 0) {
                ans += d;
                n /= d;
            }
            d++;
        }
        return ans;
    }
}

var minSteps = function(n) {
    let ans = 0;
    let d = 2;
    while (n > 1) {
        while (n % d === 0) {
            ans += d;
            n = Math.floor(n / d);
        }
        d++;
    }
    return ans;
};
